<?php
declare(strict_types=1);require dirname(__DIR__,2).'/app/bootstrap.php';require BASE_PATH.'/app/AdminUi.php';$user=Auth::requireLogin();Auth::requirePermission('customers.view');$pdo=Database::connection();$term=trim($_GET['q']??'');$sql='SELECT c.id,c.full_name,c.phone,c.email,c.nationality,c.created_at,(SELECT COUNT(*) FROM bookings b WHERE b.customer_id=c.id) bookings_count,(SELECT COUNT(*) FROM umrah_requests u WHERE u.customer_id=c.id) umrah_count,(SELECT COUNT(*) FROM service_requests s WHERE s.customer_id=c.id) service_count FROM customers c';$args=[];if($term!==''){$sql.=' WHERE c.full_name LIKE ? OR c.phone LIKE ?';$args=['%'.$term.'%','%'.$term.'%'];}$sql.=' ORDER BY c.id DESC LIMIT 500';$q=$pdo->prepare($sql);$q->execute($args);$rows=$q->fetchAll();admin_page_start('قاعدة العملاء',$user);echo '<section class="panel"><form method="get" class="inline"><input name="q" placeholder="ابحث بالاسم أو الهاتف" value="'.e($term).'"><button class="btn-sm">بحث</button></form></section><section class="panel"><table><thead><tr><th>العميل</th><th>الهاتف</th><th>البريد</th><th>الجنسية</th><th>حجوزات</th><th>عمرة</th><th>خدمات</th><th>تاريخ التسجيل</th></tr></thead><tbody>';foreach($rows as $r)echo '<tr><td>'.e($r['full_name']).'</td><td>'.e($r['phone']).'</td><td>'.e($r['email']).'</td><td>'.e($r['nationality']).'</td><td>'.(int)$r['bookings_count'].'</td><td>'.(int)$r['umrah_count'].'</td><td>'.(int)$r['service_count'].'</td><td>'.e($r['created_at']).'</td></tr>';if(!$rows)echo '<tr><td colspan="8">لا يوجد عملاء.</td></tr>';echo '</tbody></table></section>';admin_page_end();
